// Create debug utility
const DEBUG = import.meta.env.DEV;
const debugLog = DEBUG ? console.log : () => {};
const debugWarn = DEBUG ? console.warn : () => {};

// Usage
debugLog('Auth state change:', newState);
debugWarn('Performance warning:', data);

// For critical debugging that needs to be preserved
const authLogger = {
  debug: import.meta.env.DEV ? console.log : () => {},
  info: import.meta.env.DEV ? console.info : () => {},
  warn: console.warn, // Always show warnings
  error: console.error // Always show errors
};
